 using System.ComponentModel;
 using ModelContextProtocol.Server;

 var builder = WebApplication.CreateBuilder(args);

 builder.Services
     .AddMcpServer()
     .WithHttpTransport()
     .WithTools<GreetingTools>()
     .WithResources<ConfigResources>();

 var app = builder.Build();

 app.MapMcp();

 app.Run();

 // --- Tools ---

 [McpServerToolType]
 public sealed class GreetingTools
 {
     [McpServerTool(Name = "greet"), Description("Greets a user by name")]
     public static string Greet(string name) => $"Hello, {name}! Welcome to the MCP server.";

     [McpServerTool(Name = "add"), Description("Adds two numbers")]
     public static double Add(double a, double b) => a + b;
 }

 // --- Resources ---

 [McpServerResourceType]
 public sealed class ConfigResources
 {
     [McpServerResource(
         UriTemplate = "config://app/settings",
         Name = "app-settings",
         MimeType = "application/json")]
     public static string GetAppSettings() =>
         """
         {
           "appName": "McpHttpServer",
           "version": "1.0.0",
           "features": {
             "logging": true,
             "metrics": true,
             "tracing": false
           },
           "maxConnections": 100
         }
         """;

     [McpServerResource(
         UriTemplate = "config://app/environment",
         Name = "environment-info",
         MimeType = "application/json")]
     public static string GetEnvironmentInfo() =>
         System.Text.Json.JsonSerializer.Serialize(new
         {
             machineName = Environment.MachineName,
             osVersion = Environment.OSVersion.ToString(),
             runtime = System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription,
             processorCount = Environment.ProcessorCount,
             timestamp = DateTimeOffset.UtcNow,
         });
 }

